function CommunitySubmitPage({theme,onToggleTheme}){
const me=acct.useAccount(),user=me.user;React.useEffect(()=>{if(me.status==='ready'&&!user)location.replace('/masuk?kembali=%2Fkomunitas%2Ftambah')},[me.status,user]);const formRef=React.useRef(null),previewUrl=React.useRef(''),localToday=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);const [feedback,setFeedback]=React.useState(''),[busy,setBusy]=React.useState(false),[proofPreview,setProofPreview]=React.useState(''),[form,setForm]=React.useState({name:'',commodity:productNames[0],seller:'Pasar tradisional',region:'Jawa Barat',marketName:'',price:'',date:localToday(),notes:'',proof:null});const unit=productInfo(form.commodity).unit;const update=(key,value)=>setForm(current=>({...current,[key]:value}));const onPriceChange=event=>{const input=event.currentTarget,raw=input.value,caret=input.selectionStart??raw.length,digits=raw.replace(/\D/g,''),digitsBeforeCaret=raw.slice(0,caret).replace(/\D/g,'').length;update('price',digits);const formatted=formatCommunityPrice(digits);requestAnimationFrame(()=>{let position=0,count=0;while(position<formatted.length&&count<digitsBeforeCaret){if(/\d/.test(formatted[position]))count++;position++}input.setSelectionRange(position,position)})};const onPhoto=event=>{const file=event.target.files?.[0];if(!file){setForm(current=>({...current,proof:null}));if(previewUrl.current)URL.revokeObjectURL(previewUrl.current);previewUrl.current='';setProofPreview('');return}try{if(previewUrl.current)URL.revokeObjectURL(previewUrl.current);previewUrl.current=URL.createObjectURL(file);setProofPreview(previewUrl.current);setForm(current=>({...current,proof:file}));setFeedback('')}catch{setFeedback('Foto belum dapat dibaca. Coba pilih berkas lain.')}};const submit=async event=>{event.preventDefault();if(busy)return;setBusy(true);setFeedback('');try{const proof=await compressReceiptImage(form.proof),row={id:`${Date.now()}-${Math.random().toString(36).slice(2,7)}`,name:user?.nama||'',commodity:form.commodity,seller:form.seller,region:form.region,marketName:form.marketName.trim(),price:Number(form.price),unit,date:form.date,notes:form.notes.trim(),proof,comments:[],createdAt:new Date().toISOString()};if(!Number.isFinite(row.price)||row.price<500)throw new Error('Masukkan harga minimal Rp500.');const {id:_id,comments:_c,createdAt:_t,...payload}=row;await community.create(payload,user);location.assign('/komunitas')}catch(error){setFeedback(error.message||'Kiriman belum bisa disimpan.')}finally{setBusy(false)}};return <><Header theme={theme} onToggleTheme={onToggleTheme}/><main className="community-page community-submit-page"><a href="/komunitas" className="community-back-link"><ArrowRight size={15}/> Kembali ke komunitas</a><div className="community-heading community-submit-heading"><div><div className="eyebrow">KONTRIBUSI HARGA · PROTOTIPE</div><h1>Bagikan temuan harga.</h1><p>Masukkan harga yang kamu amati. Kiriman ditandai “Belum diverifikasi” dan tidak mengubah data harga PIHPS di dashboard.</p></div><PageBanner variant="pak"/></div><section className="community-form-panel community-form-standalone"><div className="community-form-heading"><div><div className="eyebrow">FORM KIRIMAN</div><h2>Tambah temuan harga</h2></div><span className="form-heading-art"><FoodIcon name={form.commodity}/><Upload size={19}/></span></div><form className="community-form" ref={formRef} onSubmit={submit}><div className="community-field-grid"><label>Nama kontributor<input value={user?.nama||''} readOnly aria-readonly="true" title="Nama diambil dari akun Anda" placeholder="Masuk terlebih dahulu"/></label><label>Komoditas<select value={form.commodity} onChange={event=>update('commodity',event.target.value)}>{productNames.map(name=><option key={name}>{name}</option>)}</select></label><label>Tempat belanja<select value={form.seller} onChange={event=>update('seller',event.target.value)}><option>Pasar tradisional</option><option>Supermarket</option></select></label><label>Provinsi<select value={form.region} onChange={event=>update('region',event.target.value)}>{regions.map(name=><option key={name}>{name}</option>)}</select></label><label className="community-field-wide">Nama pasar / toko<input value={form.marketName} onChange={event=>update('marketName',event.target.value)} required maxLength={80} placeholder="Contoh: Pasar Kosambi"/></label><label>Harga per {unit}<span className="community-price-input"><span>Rp</span><input type="text" inputMode="numeric" autoComplete="off" value={formatCommunityPrice(form.price)} onChange={onPriceChange} required placeholder="14.000" aria-label={`Harga dalam rupiah per ${unit}`} min="500"/></span></label><label>Tanggal pengamatan<input type="date" value={form.date} onChange={event=>update('date',event.target.value)} required max={localToday()}/></label><label className="community-field-wide">Catatan kondisi <span className="community-optional">opsional</span><textarea value={form.notes} onChange={event=>update('notes',event.target.value)} rows="3" maxLength={240} placeholder="Contoh: harga untuk kualitas sedang, per kilogram"/></label></div><label className="community-upload"><input type="file" accept="image/png,image/jpeg,image/webp" onChange={onPhoto}/>{proofPreview?<span className="community-photo-preview"><img src={proofPreview} alt="Pratinjau bukti harga"/><span><b>Foto bukti siap</b><small>Klik untuk mengganti foto</small></span><ImagePlus size={18}/></span>:<span className="community-upload-empty"><ImagePlus size={20}/><span><b>Tambah foto bukti</b><small>JPG, PNG, atau WebP · opsional · maks. 6 MB</small></span><Upload size={17}/></span>}</label>{form.proof&&<AiPhotoFill file={form.proof} onFill={r=>{const done=[];setForm(cur=>{const next={...cur};if(r.commodity&&productNames.includes(r.commodity)){next.commodity=r.commodity;done.push('komoditas')}if(r.price){next.price=String(r.price);done.push('harga')}if(r.seller){next.seller=r.seller;done.push('jenis tempat')}if(r.marketName){next.marketName=r.marketName;done.push('nama pasar/toko')}if(r.date&&r.date<=localToday()){next.date=r.date;done.push('tanggal')}return next});return [r.commodity&&'komoditas',r.price&&'harga',r.seller&&'jenis tempat',r.marketName&&'nama pasar/toko',r.date&&'tanggal'].filter(Boolean).join(', ')}}/>}<label className="community-consent"><input type="checkbox" required/><span>Saya menyatakan harga dan lokasi sesuai pengamatan, bukan promosi atau iklan.</span></label><button className="community-submit" disabled={busy}>{busy?'Menyimpan kiriman...':'Simpan kiriman'} <ArrowRight size={16}/></button>{feedback&&<p className="community-feedback" role="status">{feedback}</p>}<p className="community-form-note"><Info size={14}/> {community.mode==='server'?'Kiriman disimpan ke database komunitas dengan status “Belum diverifikasi”.':'Server komunitas belum dihubungkan; kiriman sementara tersimpan di browser ini.'}</p></form></section></main><BrandFooter/></>}
function SiteIntro(){const reduce=useReducedMotion(),[introDone,setIntroDone]=React.useState(()=>{try{return sessionStorage.getItem('pangan-intro-seen')==='1'}catch{return false}}),[logoTarget,setLogoTarget]=React.useState({x:0,y:0,scale:.36});React.useLayoutEffect(()=>{if(reduce||introDone){try{sessionStorage.setItem('pangan-intro-seen','1')}catch{}setIntroDone(true);return}const placeWordmark=()=>{const rect=document.querySelector('.nav .brand')?.getBoundingClientRect();if(rect)setLogoTarget({x:rect.left+rect.width*.66-window.innerWidth/2,y:rect.top+rect.height/2-window.innerHeight/2,scale:Math.min(.4,Math.max(.27,rect.width/390))})};placeWordmark();window.addEventListener('resize',placeWordmark);try{sessionStorage.setItem('pangan-intro-seen','1')}catch{}const timer=window.setTimeout(()=>setIntroDone(true),2050);return()=>{window.clearTimeout(timer);window.removeEventListener('resize',placeWordmark)}},[reduce,introDone]);if(reduce)return null;return <AnimatePresence>{!introDone&&<motion.div className="site-intro" aria-hidden="true" initial={{opacity:1}} exit={{opacity:0}} transition={{duration:.46,ease:revealEase}}><motion.span className="site-intro-wordmark" initial={{opacity:0,scale:1}} animate={{x:logoTarget.x,y:logoTarget.y,scale:logoTarget.scale,opacity:[0,1,1,0]}} transition={{x:{duration:1.2,delay:.82,ease:revealEase},y:{duration:1.2,delay:.82,ease:revealEase},scale:{duration:1.2,delay:.82,ease:revealEase},opacity:{duration:1.78,delay:.28,times:[0,.13,.72,1],ease:'easeInOut'}}}>PANGAN <i>PAS</i></motion.span></motion.div>}</AnimatePresence>}
function App(){const [theme,setTheme]=React.useState(()=>{try{return localStorage.getItem('pangan-theme')==='dark'?'dark':'light'}catch{return 'light'}});React.useLayoutEffect(()=>{document.documentElement.dataset.theme=theme;try{localStorage.setItem('pangan-theme',theme)}catch{}},[theme]);const toggleTheme=()=>{const next=theme==='dark'?'light':'dark';setTheme(next);if(acct.getAccount().user)acct.savePrefs({tema:next}).catch(()=>{})};React.useEffect(()=>{let first=true;const off=acct.subscribeAccount(s=>{if(first&&s.status==='ready'){first=false;if(s.user){setTheme(s.user.tema);acct.refreshInbox();acct.checkWatches()}}});acct.loadAccount();return off},[]);const shell=child=><><Header theme={theme} onToggleTheme={toggleTheme}/><main className="account-main">{child}</main><BrandFooter/></>;const path=location.pathname.replace(/\/+$/,'')||'/';const gated=path==='/peta'?'peta':path==='/tren'?'tren':null;const pass=useGuestPass(gated);const page=gated&&pass.status==='checking'?shell(<p className="account-loading">Memuat…</p>):gated&&pass.status==='blocked'?shell(<GuestWall feature={gated}/>):path==='/masuk'?shell(<LoginPage/>):path==='/daftar'?shell(<RegisterPage/>):path==='/profil'?shell(<ProfilePage theme={theme} onToggleTheme={toggleTheme}/>):path==='/sekitar'?shell(<NearbyPage/>):location.pathname==='/peta'?<Dashboard theme={theme} onToggleTheme={toggleTheme}/>:location.pathname==='/tren'?<TrendsPage theme={theme} onToggleTheme={toggleTheme}/>:location.pathname==='/komunitas/tambah'?<CommunitySubmitPage theme={theme} onToggleTheme={toggleTheme}/>:location.pathname==='/komunitas'?<CommunityPage theme={theme} onToggleTheme={toggleTheme}/>:<Landing theme={theme} onToggleTheme={toggleTheme}/>;return <><Ambient/><FieldEdge/><InteractionLayer/><ScrollReveal/>{page}{gated&&pass.status==='free'&&<GuestBanner left={pass.left} feature={gated}/>}{path!=='/peta'&&<AiAssistant/>}<SiteIntro/></>};createRoot(document.getElementById('root')).render(<App/>);

























